import { ArrowRight } from "lucide-react";
import { CategoryIcon } from "@/components/ui/CategoryIcon";
import { cn } from "@/lib/utils";
import type { Category, OpportunityType } from "@/lib/types";

interface CategoryCardProps {
  category: Category;
  className?: string;
}

const COLOUR_MAP: Record<OpportunityType | string, { bg: string; iconColor: string; arrowBg: string }> = {
  internship:  { bg: "bg-[#F0F7FF]", iconColor: "text-blue-600", arrowBg: "bg-white text-slate-400 group-hover:text-blue-600" },
  job:         { bg: "bg-[#FFF0F5]", iconColor: "text-pink-500", arrowBg: "bg-white text-slate-400 group-hover:text-pink-500" },
  competition: { bg: "bg-[#F0FFF4]", iconColor: "text-green-500", arrowBg: "bg-white text-slate-400 group-hover:text-green-500" },
  hackathon:   { bg: "bg-[#F5F3FF]", iconColor: "text-purple-600", arrowBg: "bg-white text-slate-400 group-hover:text-purple-600" },
  contest:     { bg: "bg-[#FFF7ED]", iconColor: "text-orange-500", arrowBg: "bg-white text-slate-400 group-hover:text-orange-500" },
  quiz:        { bg: "bg-[#F0F9FF]", iconColor: "text-sky-500", arrowBg: "bg-white text-slate-400 group-hover:text-sky-500" },
  event:       { bg: "bg-[#FFF0F5]", iconColor: "text-pink-500", arrowBg: "bg-white text-slate-400 group-hover:text-pink-500" },
  college_fest: { bg: "bg-[#F0FFF4]", iconColor: "text-emerald-500", arrowBg: "bg-white text-slate-400 group-hover:text-emerald-500" },
};

export function CategoryCard({ category, className }: CategoryCardProps) {
  const { type, label, description, iconKey } = category;
  const c = COLOUR_MAP[type] || COLOUR_MAP["event"];
  
  return (
    <a
      href={`#${type}`}
      className={cn(
        "group relative flex min-w-[160px] flex-col justify-between rounded-2xl p-5 transition-all duration-200 hover:-translate-y-1 hover:shadow-lg",
        c.bg, className
      )}
      aria-label={`Explore ${label}`}
    >
      <div className="flex flex-col gap-4">
        <div className={cn("flex h-10 w-10 items-center justify-center rounded-full bg-white shadow-sm", c.iconColor)}>
          <CategoryIcon iconKey={iconKey} size={18} />
        </div>
        
        <div className="flex flex-col gap-1">
          <h3 className="text-[15px] font-bold text-slate-900">{label}</h3>
          <p className="text-[12px] text-slate-600 leading-snug">{description}</p>
        </div>
      </div>
      
      <div className={cn("mt-6 flex h-7 w-7 items-center justify-center rounded-full shadow-sm transition-colors", c.arrowBg)}>
        <ArrowRight size={14} />
      </div>
    </a>
  );
}
